files.examples/01_tenant_column.sql:
-- LEARN(sql.modeling.multi-tenant): the tenant is part of every key, so no row can point across tenants.
CREATE TABLE tenants (id int PRIMARY KEY, name text NOT NULL);
CREATE TABLE projects (
  id        int  PRIMARY KEY,
  tenant_id int  NOT NULL REFERENCES tenants,
  name      text NOT NULL,
  UNIQUE (tenant_id, id)                   -- the target for tenant-aware FKs
);
INSERT INTO tenants VALUES (1, 'Kuzey'), (2, 'Güney');
INSERT INTO projects VALUES (10, 1, 'Checkout'), (20, 2, 'Checkout');

-- Naive: the FK proves project 10 exists, not that it is Güney's.
CREATE TABLE requirements_naive (
  id         int  PRIMARY KEY,
  tenant_id  int  NOT NULL REFERENCES tenants,
  project_id int  NOT NULL REFERENCES projects,
  code       text NOT NULL
);
INSERT INTO requirements_naive VALUES (1, 2, 10, 'REQ-1');   -- accepted

-- Tenant-aware: the FK includes tenant_id, and so does uniqueness.
CREATE TABLE requirements (
  id         int  PRIMARY KEY,
  tenant_id  int  NOT NULL REFERENCES tenants,
  project_id int  NOT NULL,
  code       text NOT NULL,
  UNIQUE (tenant_id, code),
  FOREIGN KEY (tenant_id, project_id) REFERENCES projects (tenant_id, id)
);
CREATE INDEX ON requirements (tenant_id, project_id);
INSERT INTO requirements VALUES (1, 1, 10, 'REQ-1'), (2, 2, 20, 'REQ-1');

-- Every query filters by tenant. Forget it once, and the page shows both.
SELECT id, code, project_id FROM requirements WHERE tenant_id = 2 ORDER BY id;
SELECT tenant_id, id, code FROM requirements ORDER BY id;

-- Güney's requirement in Kuzey's project: (2, 10) is not a project.
INSERT INTO requirements VALUES (3, 2, 10, 'REQ-2');

files.examples/02_schema_per_tenant.sql:
-- One schema per tenant with the same tables in each. search_path picks
-- the tenant, so queries carry no tenant_id at all.
CREATE SCHEMA tenant_kuzey;
CREATE SCHEMA tenant_guney;
CREATE TABLE tenant_kuzey.requirements (id int PRIMARY KEY, code text NOT NULL UNIQUE);
CREATE TABLE tenant_guney.requirements (id int PRIMARY KEY, code text NOT NULL UNIQUE);
INSERT INTO tenant_kuzey.requirements VALUES (1, 'REQ-1'), (2, 'REQ-2');
INSERT INTO tenant_guney.requirements VALUES (1, 'REQ-1');

-- Per request, inside its transaction. SET LOCAL ends with the
-- transaction, so a pooled connection can't carry it to the next request.
SET LOCAL search_path TO tenant_guney;
SELECT id, code FROM requirements ORDER BY id;

-- A report across tenants is one query per schema.
SELECT 'guney' AS tenant, count(*) AS requirements FROM tenant_guney.requirements
UNION ALL
SELECT 'kuzey', count(*) FROM tenant_kuzey.requirements
ORDER BY tenant;

-- Every migration runs once per schema. One that stopped halfway leaves
-- the tenants on different schemas.
ALTER TABLE tenant_kuzey.requirements ADD COLUMN priority smallint NOT NULL DEFAULT 3;
SELECT table_schema, count(*) AS columns
FROM information_schema.columns
WHERE table_schema LIKE 'tenant\_%' AND table_name = 'requirements'
GROUP BY table_schema
ORDER BY table_schema;

-- The new application code expects the column; Güney never got it.
SELECT id, code, priority FROM requirements ORDER BY id;

files.examples/03_rls.sql:
-- Column tenancy enforced by the database: row-level security.
CREATE TABLE requirements (
  tenant_id int  NOT NULL DEFAULT current_setting('app.tenant')::int,
  id        int  PRIMARY KEY,
  code      text NOT NULL,
  UNIQUE (tenant_id, code)
);
INSERT INTO requirements VALUES (1, 1, 'REQ-1'), (1, 2, 'REQ-2'), (2, 3, 'REQ-1');

ALTER TABLE requirements ENABLE ROW LEVEL SECURITY;
-- The table owner bypasses policies unless they are forced on it too.
ALTER TABLE requirements FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON requirements
  USING (tenant_id = current_setting('app.tenant')::int);

-- Superusers and BYPASSRLS roles skip every policy. The app role must not.
SELECT rolsuper, rolbypassrls FROM pg_roles WHERE rolname = current_user;

-- Per request, inside its transaction: true means "local to it".
SELECT set_config('app.tenant', '2', true);

-- No tenant filter anywhere below: the policy adds it.
SELECT tenant_id, id, code FROM requirements ORDER BY id;
UPDATE requirements SET code = 'REQ-9' WHERE id = 1;     -- tenant 1's row
INSERT INTO requirements (id, code) VALUES (4, 'REQ-2'); -- tenant_id from the setting
SELECT tenant_id, id, code FROM requirements ORDER BY id;

-- A row for another tenant fails the policy's check.
INSERT INTO requirements (tenant_id, id, code) VALUES (1, 5, 'REQ-3');
